fn remove_odd_numbers(arr: &[i32]) -> Vec<i32> {
    // Create a new vector to hold the even numbers
    let mut even_numbers = Vec::new();
    
    // Iterate over the input array
    for &num in arr.iter() {
        // Check if the number is even
        if num % 2 == 0 {
            // If it is even, push it to the new vector
            even_numbers.push(num);
        }
    }
    
    // Return the vector containing only even numbers
    even_numbers
}